INSERT INTO task_records(source_ref,kind,trigger,state,phase,terminal,created_at,started_at,updated_at,finished_at,configuration_revision,configuration_fingerprint,resource_kind,resource_id,request_id,total,completed,succeeded,failed,skipped,removed,error_code,result_ref) SELECT source_ref,kind,trigger,state,phase,terminal,created_at,started_at,updated_at,finished_at,configuration_revision,configuration_fingerprint,resource_kind,resource_id,request_id,total,completed,succeeded,failed,skipped,removed,error_code,result_ref FROM hps_health_task_projection WHERE source_id=?1 ON CONFLICT(source_ref) DO UPDATE SET version=task_records.version+1,state=excluded.state,phase=excluded.phase,terminal=excluded.terminal,started_at=excluded.started_at,updated_at=max(task_records.updated_at,excluded.updated_at),finished_at=excluded.finished_at,configuration_revision=coalesce(task_records.configuration_revision,excluded.configuration_revision),configuration_fingerprint=excluded.configuration_fingerprint,resource_kind=excluded.resource_kind,resource_id=excluded.resource_id,request_id=excluded.request_id,total=excluded.total,completed=excluded.completed,succeeded=excluded.succeeded,failed=excluded.failed,skipped=excluded.skipped,removed=excluded.removed,error_code=excluded.error_code,result_ref=excluded.result_ref;